head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger2_onclick = function(e) {
    dmBooking.set("porCd", "CNSHA");
};
scwin.evInputOnViewChange = function(info) {
    var id = this.getOriginalID();
    var val = info.newValue.trim();
    //$p.log( "scwin.evInputOnViewChange===" + ipbPorCd.getValue() + "..." + dmBooking.get("porCd") +"..."+ JSON.stringify(info) );
    console.log("scwin.evInputOnViewChange===" + ipbPorCd.getValue() + "..." + dmBooking.get("porCd") + "..." + JSON.stringify(info));
};
scwin.test1 = function(data) {
    //$p.log( "scwin.test1...."+data );
    console.log("scwin.test1...." + data);
    return data.toUpperCase();
};
scwin.test2 = function(data) {
    return data;
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#ipbPorCd', 'key-sequence', {
        sequence: 'wsx'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#ipbPorCd', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "ipbPorCd.focus()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "ipbPorCd.click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "ipbPorCd.click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ipbPorCd').value = ''");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "300");
    //WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 1", "true");
    WebSquare.wUnit.addCommand("pause", "1300");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
